Set-StrictMode -Version Latest

function Read-TaskStore {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return @()
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        return @()
    }

    $parsed = ConvertFrom-Json -InputObject $content -DateKind String
    return @($parsed)
}

function Write-TaskStore {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    $json = ConvertTo-Json -InputObject @($Tasks) -Depth 8
    Write-AtomicTextFile -Path $Path -Content "$json`n"
}

function Write-AtomicTextFile {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Content
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    $temporary = "$Path.$PID.$([guid]::NewGuid().ToString('N')).tmp"
    try {
        [System.IO.File]::WriteAllText($temporary, $Content, [System.Text.UTF8Encoding]::new($false))
        [System.IO.File]::Move($temporary, $Path, $true)
    }
    finally {
        Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue
    }
}

function Get-UndoPath {
    param([Parameter(Mandatory)][string]$DataPath)

    return "$DataPath.undo.json"
}

function Read-UndoRecord {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw 'No undo is available.'
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        throw 'The undo record is invalid.'
    }

    return ConvertFrom-Json -InputObject $content -DateKind String
}

function Write-UndoRecord {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)]$Record
    )

    $json = ConvertTo-Json -InputObject $Record -Depth 8
    Write-AtomicTextFile -Path $Path -Content "$json`n"
}

function Write-Mutation {
    param(
        [Parameter(Mandatory)][string]$DataPath,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$PreviousTasks,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$UpdatedTasks,
        [Parameter(Mandatory)]$UndoRecord
    )

    Write-TaskStore -Path $DataPath -Tasks $UpdatedTasks
    try {
        Write-UndoRecord -Path (Get-UndoPath -DataPath $DataPath) -Record $UndoRecord
    }
    catch {
        Write-TaskStore -Path $DataPath -Tasks $PreviousTasks
        throw
    }
}

function Invoke-TaskUndo {
    param([Parameter(Mandatory)][string]$DataPath)

    $undoPath = Get-UndoPath -DataPath $DataPath
    $record = Read-UndoRecord -Path $undoPath
    $tasks = @(Read-TaskStore -Path $DataPath)
    $operation = [string]$record.operation
    $index = [int]$record.index
    $taskId = [int]$record.taskId

    switch ($operation) {
        'add' {
            if ($index -lt 0 -or $index -ge $tasks.Count -or [int]$tasks[$index].id -ne $taskId) {
                throw 'The undo record does not match the task store.'
            }
            $restored = @(
                for ($current = 0; $current -lt $tasks.Count; $current++) {
                    if ($current -ne $index) {
                        $tasks[$current]
                    }
                }
            )
        }
        'complete' {
            if ($index -lt 0 -or $index -ge $tasks.Count -or [int]$tasks[$index].id -ne $taskId -or
                $null -eq $record.previousStatus) {
                throw 'The undo record does not match the task store.'
            }
            $restored = @($tasks)
            $restored[$index].status = [string]$record.previousStatus
        }
        'remove' {
            if ($index -lt 0 -or $index -gt $tasks.Count -or $null -eq $record.task) {
                throw 'The undo record does not match the task store.'
            }
            $restored = @(
                for ($current = 0; $current -le $tasks.Count; $current++) {
                    if ($current -eq $index) {
                        $record.task
                    }
                    if ($current -lt $tasks.Count) {
                        $tasks[$current]
                    }
                }
            )
        }
        default {
            throw 'The undo record is invalid.'
        }
    }

    $claimPath = "$undoPath.$PID.$([guid]::NewGuid().ToString('N')).claim"
    [System.IO.File]::Move($undoPath, $claimPath)
    $storeWritten = $false
    try {
        Write-TaskStore -Path $DataPath -Tasks $restored
        $storeWritten = $true
        Remove-Item -LiteralPath $claimPath -Force
    }
    catch {
        if ($storeWritten) {
            Write-TaskStore -Path $DataPath -Tasks $tasks
        }
        if ((Test-Path -LiteralPath $claimPath) -and -not (Test-Path -LiteralPath $undoPath)) {
            [System.IO.File]::Move($claimPath, $undoPath)
        }
        throw
    }

    return [pscustomobject]@{
        undone = $operation
        taskId = $taskId
    }
}

function ConvertFrom-TaskForgeArguments {
    param([AllowEmptyCollection()][string[]]$Arguments)

    $options = [ordered]@{}
    for ($index = 0; $index -lt $Arguments.Count; $index++) {
        $token = $Arguments[$index]
        if (-not $token.StartsWith('--')) {
            throw "Unexpected argument: $token"
        }

        $name = $token.Substring(2)
        if ([string]::IsNullOrWhiteSpace($name)) {
            throw 'Option name cannot be empty.'
        }
        if ($options.Contains($name)) {
            throw "Duplicate option: --$name"
        }

        if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
            $options[$name] = $Arguments[++$index]
        }
        else {
            $options[$name] = $true
        }
    }

    return $options
}

function Get-RequiredOption {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][string]$Name
    )

    if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool] -or
        [string]::IsNullOrWhiteSpace([string]$Options[$Name])) {
        throw "Missing required option: --$Name"
    }
    return [string]$Options[$Name]
}

function Assert-KnownOptions {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Allowed
    )

    foreach ($name in $Options.Keys) {
        if ($name -notin $Allowed) {
            throw "Unknown option: --$name"
        }
    }
}

function Write-TaskForgeOutput {
    param(
        [Parameter(Mandatory)]$Value,
        [Parameter(Mandatory)][bool]$AsJson
    )

    if ($AsJson) {
        ConvertTo-Json -InputObject $Value -Depth 8 -Compress
    }
    else {
        [string]$Value
    }
}

